import { Group, Mesh, PlaneGeometry, Vector2, Color } from 'three/webgpu';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, float, clamp } from 'three/tsl';
import { gsap } from 'gsap';
import { dummy } from '@/primitives';
import { dummy as textDummy } from '@/text';

export default function createNode(config, ctx) {
  const { Group: ThreeGroup } = ctx.THREE;

  // --------------------
  // Panel geometry
  // --------------------
  const panelWidth = 3.4;
  const panelHeight = 1.9;
  const panelGeom = new PlaneGeometry(panelWidth, panelHeight, 1, 1);

  // Gradient colors
  const gradTop = new Color('#1a1a22');
  const gradBottom = new Color('#111116');
  const borderColor = new Color('#26262f');

  // Gradient node
  const gradientNode = mix(
    vec3(float(gradTop.r), float(gradTop.g), float(gradTop.b)),
    vec3(float(gradBottom.r), float(gradBottom.g), float(gradBottom.b)),
    uv().y
  );

  // Simple border mask (0.006 unit wide)
  const borderWidth = 0.006 / Math.min(panelWidth, panelHeight);
  const uvPos = uv();
  const edgeMask = clamp(
    min(
      min(uvPos.x, 1.0 - uvPos.x),
      min(uvPos.y, 1.0 - uvPos.y)
    ),
    0.0,
    borderWidth
  );
  const borderMask = float(1.0).sub(edgeMask);

  const baseColorNode = mix(
    vec3(float(borderColor.r), float(borderColor.g), float(borderColor.b)),
    gradientNode,
    borderMask
  );

  const panelMat = new MeshStandardNodeMaterial();
  panelMat.baseColorNode = baseColorNode;
  panelMat.roughness = 0.6;
  panelMat.metalness = 0.2;
  panelMat.clearcoat = 0.1;
  panelMat.transparent = true;
  panelMat.opacity = 0; // start hidden for fade‑up

  const panelMesh = new Mesh(panelGeom, panelMat);
  panelMesh.position.set(0, 0, 0);

  // --------------------
  // Text elements
  // --------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const textGroup = new ThreeGroup();

  // Helper to create and place text
  function addText(content, opts, position, zOffset = 0.03) {
    const txt = ctx.fontAtlas.createText(content, opts);
    txt.position.set(position.x, position.y, zOffset);
    txt.scale.set(1, 1, 1);
    textGroup.add(txt);
    return txt;
  }

  // Quote mark (oversized)
  const quoteMarkOpts = {
    fontSize: 62,
    color: '#ff2a38',
    align: 'left',
  };
  const qMarkPos = new Vector2(
    -panelWidth / 2 + 0.5,
    panelHeight / 2 - 0.5
  );
  const quoteMark = addText('“', quoteMarkOpts, qMarkPos, 0.04);
  // Scale height to approx 0.62 units
  quoteMark.scale.setScalar(0.62 / (quoteMarkOpts.fontSize / 100));

  // Quote
  const quoteOpts = {
    fontSize: 20,
    color: '#e8ecf2',
    align: 'left',
  };
  const quotePos = new Vector2(
    -panelWidth / 2 + 0.5,
    qMarkPos.y - 0.62 - 0.25
  );
  const quoteText = addText(
    'The bezel action alone is worth the wait. Nothing else on my wrist feels this considered.',
    quoteOpts,
    quotePos
  );

  // Attribution
  const attrOpts = {
    fontSize: 13,
    color: '#e8ecf2',
    align: 'left',
  };
  const attrPos = new Vector2(
    -panelWidth / 2 + 0.5,
    quotePos.y - 0.25
  );
  const attribution = addText('M. OKAFOR', attrOpts, attrPos);

  // Accent rule (emissive)
  const ruleWidth = 0.2;
  const ruleHeight = 0.02;
  const ruleGeom = new PlaneGeometry(ruleWidth, ruleHeight);
  const ruleMat = new MeshBasicNodeMaterial();
  ruleMat.baseColorNode = vec3(float(1), float(0), float(0)); // placeholder red
  ruleMat.emissiveIntensity = 1.4;
  ruleMat.transparent = true;
  const ruleMesh = new Mesh(ruleGeom, ruleMat);
  ruleMesh.position.set(
    attrPos.x - ruleWidth / 2 - 0.05,
    attrPos.y + 0.01,
    0.04
  );
  textGroup.add(ruleMesh);

  // Caption
  const capOpts = {
    fontSize: 9,
    color: '#e8ecf2',
    align: 'left',
  };
  const capPos = new Vector2(
    -panelWidth / 2 + 0.5,
    attrPos.y - 0.2
  );
  const caption = addText('COLLECTOR SINCE 2019', capOpts, capPos);

  // --------------------
  // Assemble group
  // --------------------
  const root = new ThreeGroup();
  root.add(panelMesh);
  root.add(textGroup);

  // Initial offset for fade‑up
  root.position.y += 0.2;
  root.visible = true;

  // --------------------
  // Animations
  // --------------------
  const timelines = [];

  // Panel fade‑up
  const panelTl = gsap.timeline();
  panelTl.to(panelMat, {
    opacity: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  });
  panelTl.to(
    root.position,
    { y: root.position.y - 0.2, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
    0
  );
  timelines.push(panelTl);

  // Quote mark settle
  const markTl = gsap.timeline();
  markTl.fromTo(
    quoteMark.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'cubic-bezier(0.165,0.84,0.44,1)',
    }
  );
  timelines.push(markTl);

  // --------------------
  // Primitives (none)
  // --------------------
  // (no primitives to apply)

  // --------------------
  // Cleanup
  // --------------------
  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    panelGeom.dispose();
    panelMat.dispose();
    ruleGeom.dispose();
    ruleMat.dispose();
    // Font atlas texts are disposed by three's dispose when group is GC'd
  };

  // Attach empty handlers container
  root.userData.handlers = {};

  return root;
}
